import type { CartLine } from '#shared/types/cart'
import type { Quote } from '#server/utils/quote'

export interface Order extends Quote {
  id: string
  lines: CartLine[]
}

/** Orders kept in server memory, keyed by id. They are lost on restart. */
const orders = new Map<string, Order>()

export function saveOrder(id: string, lines: CartLine[], quote: Quote): Order {
  const order: Order = { id, lines: lines.map(line => ({ ...line })), ...quote }
  orders.set(id, order)
  return order
}

export function findOrder(id: string): Order | undefined {
  return orders.get(id)
}

import type { CartLine } from '#shared/types/cart'
import { randomUUID } from 'node:crypto'
import { createError, defineEventHandler, readBody } from 'h3'
import { computeQuote } from '#server/utils/quote'
import { saveOrder } from '#server/utils/orders'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: CartLine[], code?: string }>(event)
  if (!Array.isArray(body?.lines))
    throw createError({ statusCode: 400, statusMessage: 'lines must be an array' })
  const quote = computeQuote(body.lines, body.code)
  const order = saveOrder(randomUUID(), body.lines, quote)
  return { id: order.id, subtotal: order.subtotal, discount: order.discount, total: order.total }
})

import { createError, defineEventHandler, getRouterParam } from 'h3'
import { findOrder } from '#server/utils/orders'

export default defineEventHandler((event) => {
  const order = findOrder(getRouterParam(event, 'id') ?? '')
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return order
})
